    if (/AGRAVO|APELACAO|\bRECURSO\b|\bRESP\b/.test(t)) return "recurso";
    if (/EMBARGOS|\bED\b/.test(t)) return "embargos";
    if (/CONTESTACAO/.test(t)) return "contestacao";
    if (/\bREPLICA\b/.test(t)) return "replica";
