    fichas_processo: P.length, fichas_total: P.length + C.length, cnj_distintos: ordem.length, sem_numero: semNum.length, casos: C.length,
    arquivadas: P.filter(arquivada).length,
    ativos: temStatus ? cnj.filter(function (g) { return g.some(ativa); }).length + semNum.filter(ativa).length : null,
    valor_total: cnj.reduce(function (s, g) { return s + maior(g); }, 0) + semNum.reduce(function (s, p) { return s + vb(p.valor_causa); }, 0) + C.reduce(function (s, c) { return s + vb(c.valor_causa); }, 0),
    unicos: cnj.map(function (g) { return g[0]; }).concat(semNum),
