      natureza: natureza, funcao: funcao, informativo: !!papel && papel.papel !== "atuacao", papel_historico: papel ? papel.papel : undefined, origem_historico: papel ? papel.origem : undefined, motivo_historico: papel ? papel.motivo : undefined,
