    funcoes[NUCLEO.FUNCOES[a.funcao].rotulo] = (funcoes[NUCLEO.FUNCOES[a.funcao].rotulo] || 0) + 1;
    areas[a.area === "insolvencia" ? "Insolvência" : "Cível"] = (areas[a.area === "insolvencia" ? "Insolvência" : "Cível"] || 0) + 1;
    esforcoTotal += a.esforco;
