  var histCopia = filtradas.filter(function (a) { return a.papel_historico === "movimentacao" && a.origem_historico === "copia_tribunal"; });
  var histInformativos = filtradas.filter(function (a) { return (a.papel_historico === "movimentacao" && a.origem_historico !== "copia_tribunal") || a.papel_historico === "nota"; });
  var revisar = filtradas.filter(function (a) { return a.papel_historico === "revisar"; });
