    historicos_informativos: histInformativos.map(function (a) { return { numero_processo: a.numero_processo, data: a.data_efetiva || a.data, origem: a.origem_historico, motivo: a.motivo_historico, descricao: a.descricao }; }),
    quantidade_andamentos: tipos["Andamento"] || 0,
    quantidade_processos_movimentados: movCount,
    movimentados_detalhe: movDetalhe,
    processos_com_ato: Object.keys(comAto).length,
    media_atividades_por_processo_movimentado: movCount ? Math.round((totalAtividades / movCount) * 100) / 100 : 0.0,
