// Desenha uma linha justificada (coordenadas reais do jsPDF, fonte já definida),
// distribuindo o espaço que sobra entre as palavras. Devolve false quando não há
// o que justificar (uma palavra só, ou linha que já ocupa a largura toda).
function textoJustificado(doc, linha, x, yReal, largura) {
  const ws = String(linha).trim().split(/\s+/);
  if (ws.length < 2 || doc.getTextWidth(ws.join(" ")) >= largura) return false;
  const soma = ws.reduce((s, w) => s + doc.getTextWidth(w), 0);
  const gap = (largura - soma) / (ws.length - 1);
  let xx = x;
  ws.forEach((w) => { doc.text(w, xx, yReal); xx += doc.getTextWidth(w) + gap; });
  return true;
}

